mapper.select:
SELECT * FROM forecast_version
AND (version_no LIKE CONCAT('%', #{keyword}, '%') OR status LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE forecast_detail fd
JOIN (
    SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS seq
    FROM forecast_detail
    WHERE version_id=#{versionId}
) ranked ON ranked.id=fd.id
SET fd.source_row_no=ranked.seq, fd.priority_seq=ranked.seq
WHERE fd.version_id=#{versionId}

mapper.select:
SELECT id, version_id, factory_code, material_id, material_name, business_line, form_type, project, platform, mold, status, plan_month, forecast_qty, priority_seq FROM forecast_detail
version_id = #{versionId}
AND (material_id LIKE CONCAT('%', #{keyword}, '%') OR material_name LIKE CONCAT('%', #{keyword}, '%') OR factory_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY priority_seq, source_row_no, id, plan_month LIMIT #{offset}, #{pageSize}

SELECT material_id, factory_code, MAX(material_name) AS material_name, MAX(form_type) AS form_type, MAX(project) AS project, MAX(platform) AS platform, MAX(mold) AS mold, MAX(status) AS status FROM forecast_detail
version_id = #{versionId}
AND (material_id LIKE CONCAT('%', #{keyword}, '%') OR material_name LIKE CONCAT('%', #{keyword}, '%') OR factory_code LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY factory_code, material_id ORDER BY material_id, factory_code LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM forecast_detail
version_id = #{versionId}
AND (material_id LIKE CONCAT('%', #{keyword}, '%') OR material_name LIKE CONCAT('%', #{keyword}, '%') OR factory_code LIKE CONCAT('%', #{keyword}, '%'))
